def merge_intervalos(intervalos):
    if not intervalos:
        return []
    ordenados = sorted(intervalos)
    mesclados = [list(ordenados[0])]
    for inicio, fim in ordenados[1:]:
        if inicio <= mesclados[-1][1]:
            mesclados[-1][1] = max(mesclados[-1][1], fim)
        else:
            mesclados.append([inicio, fim])
    return [tuple(item) for item in mesclados]

print(merge_intervalos([(1, 3), (2, 6), (8, 10)]))
